import urllib.request, hashlib, json, concurrent.futures
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
urls={'pdb':base+'examples/5dfr_solv-cube_equil.pdb','script':base+'examples/benchmark.py','amber99sb':base+'wrappers/python/openmm/app/data/amber99sb.xml','tip3p':base+'wrappers/python/openmm/app/data/tip3p.xml','pypi':'https://pypi.org/pypi/openmm/8.2.0/json','tag':'https://api.github.com/repos/openmm/openmm/git/ref/tags/8.2.0'}
def fetch(item):
 name,url=item
 try:
  raw=urllib.request.urlopen(url,timeout=25).read()
  out={'name':name,'url':url,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
  if name=='script':
   lines=raw.decode().splitlines(); out['relevant_lines']=[x for x in lines if any(s in x for s in ['5dfr','LangevinMiddle','hydrogenMass','ConstraintTolerance','amber99sb','tip3p','seconds','cutoff','precision'])]
  if name=='pdb': out['atoms']=sum(x.startswith((b'ATOM  ',b'HETATM')) for x in raw.splitlines())
  if name=='pypi':
   obj=json.loads(raw);out['requires_python']=obj['info']['requires_python'];out['wheels']=[x['filename'] for x in obj['urls'] if 'manylinux' in x['filename']]
  if name=='tag':out['tag']=json.loads(raw)
  return out
 except Exception as e:return {'name':name,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
 for result in pool.map(fetch,urls.items()):print(json.dumps(result))
PY"

